const c = global.get("m3ForecastContract");
try {
  c.authorizeBearer(msg.req && msg.req.headers && msg.req.headers.authorization, env.get("M3_SOURCE_READ_TOKEN"));
  const stationId = msg.req && msg.req.params && msg.req.params.station_id;
  c.configuredStation(stationId, env.get("M3_STATIONS_JSON"));
  c.validateConfiguredUrl(env.get("M3_SOURCE_RECORDS_URL"));
  const request = c.validateObservationRequest({ stationId, query: msg.req.query, cursorSecret: env.get("M3_CURSOR_SECRET") });
  const mapping = c.mappingFromJson(env.get("M3_FIELD_MAPPING_JSON"));
  msg.m3 = { route: "observations", stationId, request, mapping, sourceStation: encodeURIComponent(stationId), start: encodeURIComponent(request.start), end: encodeURIComponent(request.end) };
  c.fixedRequestMessage(msg, { token: env.get("M3_SOURCE_RECORDS_READ_TOKEN") });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  const records = c.extractRecordEnvelope(msg.payload, { maxBytes: 4194304, maxRecords: 50000 });
  const points = c.aggregateObservations({ stationId: msg.m3.stationId, records, mapping: msg.m3.mapping, start: msg.m3.request.start, end: msg.m3.request.end });
  const page = c.paginatePoints({ points, stationId: msg.m3.stationId, start: msg.m3.request.start, end: msg.m3.request.end, offset: msg.m3.request.offset, pageSize: 512, cursorSecret: env.get("M3_CURSOR_SECRET") });
  const stationId = msg.m3.stationId;
  delete msg.m3;
  c.jsonResponse(msg, { status: "ok", data: { station_id: stationId, timezone: "Asia/Shanghai", interval_seconds: 900, points: page.points, next_cursor: page.next_cursor } });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

