const c = global.get("m3ForecastContract");
try {
  c.authorizeBearer(msg.req && msg.req.headers && msg.req.headers.authorization, env.get("M3_SOURCE_READ_TOKEN"));
  c.validateEmptyQuery(msg.req.query);
  const alert = c.validateAlertRequest(msg.payload);
  const mode = env.get("M3_ALERT_SINK_MODE");
  msg.m3 = { route: "alert" };
  if (mode === "log") {
    node.warn({ event: "m3_worker_alert", station_id: alert.station_id, task: alert.task, error_code: alert.error_code, at: alert.at });
    msg.payload = alert;
    return [msg, null, null];
  }
  if (mode === "http") {
    c.validateConfiguredUrl(env.get("M3_ALERT_SINK_URL"));
    c.fixedRequestMessage(msg, { token: env.get("M3_ALERT_SINK_TOKEN"), payload: alert, contentType: true });
    return [null, msg, null];
  }
  throw new c.ContractError("source_not_configured", "alert sink mode is not configured");
} catch (error) { return [null, null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
delete msg.m3;
c.jsonResponse(msg, c.alertAcknowledgement());
return msg;

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  if (Buffer.byteLength(JSON.stringify(msg.payload)) > 65536) throw new c.ContractError("payload_too_large", "alert sink response is too large");
  c.validateAlertSinkAcknowledgement(msg.payload);
  delete msg.m3;
  c.jsonResponse(msg, c.alertAcknowledgement());
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  const authorize = c.validateDashboardAuthInput(msg.req.query, msg.req.headers && msg.req.headers.authorization);
  c.validateConfiguredUrl(env.get("M3_DASHBOARD_AUTH_URL"));
  if (msg.req.query && Object.prototype.hasOwnProperty.call(msg.req.query, "token")) delete msg.req.query.token;
  msg.m3 = { route: "dashboard" };
  c.fixedRequestMessage(msg, { token: authorize, payload: {}, contentType: true });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "unauthorized");
  if (Buffer.byteLength(JSON.stringify(msg.payload)) > 65536) throw new c.ContractError("payload_too_large", "authorization response is too large");
  const stationId = c.validateDashboardAuthorization(msg.payload);
  c.configuredStation(stationId, env.get("M3_STATIONS_JSON"));
  c.validateConfiguredUrl(env.get("M3_NOCOBASE_BASE_URL"), "/");
  msg.m3.stationId = stationId;
  msg.m3.latestFilter = encodeURIComponent(JSON.stringify({ station_id: stationId }));
  c.fixedRequestMessage(msg, { token: env.get("M3_DASHBOARD_READ_TOKEN") });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  const rows = c.extractNocoBasePage(msg.payload, { maxBytes: 2097152, maxRows: 1, page: 1, pageSize: 1, mode: "complete" });
  msg.m3.latest = rows.length === 0 ? null : rows[0];
  msg.m3.actualWindow = c.deriveDashboardActualWindow({ latest: msg.m3.latest, stationId: msg.m3.stationId });
  msg.m3.batchFilter = encodeURIComponent(JSON.stringify({ station_id: msg.m3.stationId, write_state: "complete" }));
  c.fixedRequestMessage(msg, { token: env.get("M3_DASHBOARD_READ_TOKEN") });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  const rows = c.extractNocoBasePage(msg.payload, { maxBytes: 262144, maxRows: 7, page: 1, pageSize: 7, mode: "head" });
  const selected = c.selectAcceptanceBatches(rows, msg.m3.stationId);
  msg.m3.batches = selected.batches;
  msg.m3.runId = selected.runId;
  if (selected.runId === null) {
    msg.m3.points = [];
    msg.m3.evaluations = [];
    return [null, msg, null];
  }
  msg.m3.pointFilterStation = encodeURIComponent(msg.m3.stationId);
  msg.m3.pointFilterRun = encodeURIComponent(selected.runId);
  c.fixedRequestMessage(msg, { token: env.get("M3_DASHBOARD_READ_TOKEN") });
  return [msg, null, null];
} catch (error) { return [null, null, c.toErrorMessage(msg, error)]; }

