const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  const rows = c.extractNocoBasePage(msg.payload, { maxBytes: 1048576, maxRows: 672, page: 1, pageSize: 672, mode: "complete" });
