} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  msg.m3.evaluations = c.extractNocoBasePage(msg.payload, { maxBytes: 262144, maxRows: 4, page: 1, pageSize: 4, mode: "complete" });
  if (!msg.m3.actualWindow) throw new c.ContractError("dashboard_contract_invalid", "actual window is unavailable");
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.validateConfiguredUrl(env.get("M3_SOURCE_RECORDS_URL"));
  if (!msg.m3.actualWindow) throw new c.ContractError("dashboard_contract_invalid", "actual window is unavailable");
  msg.m3.actualStart = encodeURIComponent(msg.m3.actualWindow.start);
  msg.m3.actualEnd = encodeURIComponent(msg.m3.actualWindow.end);
  msg.m3.sourceStation = encodeURIComponent(msg.m3.stationId);
  msg.m3.mapping = c.mappingFromJson(env.get("M3_FIELD_MAPPING_JSON"));
  c.fixedRequestMessage(msg, { token: env.get("M3_SOURCE_RECORDS_READ_TOKEN") });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }

const c = global.get("m3ForecastContract");
try {
  c.requireHttpSuccess(msg.statusCode, "upstream_failed");
  const records = c.extractRecordEnvelope(msg.payload, { maxBytes: 4194304, maxRecords: 50000 });
  const start = decodeURIComponent(msg.m3.actualStart);
  const end = decodeURIComponent(msg.m3.actualEnd);
  const actuals = c.aggregateObservations({ stationId: msg.m3.stationId, records, mapping: msg.m3.mapping, start, end });
  const acceptance = c.buildAcceptanceSummary({ stationId: msg.m3.stationId, batches: msg.m3.batches, points: msg.m3.points, evaluations: msg.m3.evaluations });
  const data = c.buildDashboard({ stationId: msg.m3.stationId, latest: msg.m3.latest, actuals, acceptance, emptyState: "initializing" });
  delete msg.m3;
  c.jsonResponse(msg, { status: "ok", data });
  return [msg, null];
} catch (error) { return [null, c.toErrorMessage(msg, error)]; }
